"""Run live PatchCore anomaly detection from a USB/webcam camera (camera index 0 by default)."""

from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import time

# Anomalib's exported PyTorch model format requires opting in to load trusted model code.
# Only use model files generated by this project or obtained from a trusted source.
os.environ.setdefault("TRUST_REMOTE_CODE", "1")

import cv2
import numpy as np
import torch
from anomalib.deploy import TorchInferencer

from common import EXPORTED_MODEL, PROJECT_ROOT, THRESHOLD_FILE


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--camera", type=int, default=0, help="OpenCV camera index (default: 0, usually /dev/video0).")
    parser.add_argument("--model", default=str(EXPORTED_MODEL), help="Path to the exported PatchCore .pt model.")
    parser.add_argument("--threshold", type=float, default=None, help="Override the image anomaly threshold. Otherwise results/analysis/threshold.json is used.")
    parser.add_argument("--threshold-file", default=str(THRESHOLD_FILE), help="JSON file created by analyze_results.py.")
    parser.add_argument("--mask-percentile", type=float, default=98.0, help="Percentile used to visualize high-response regions in the anomaly map (default: 98).")
    parser.add_argument("--min-area", type=int, default=120, help="Minimum contour area in pixels before drawing a box.")
    parser.add_argument("--width", type=int, default=0, help="Optional capture width; 0 keeps the camera default.")
    parser.add_argument("--height", type=int, default=0, help="Optional capture height; 0 keeps the camera default.")
    parser.add_argument("--save-video", default=None, help="Optional output MP4 path for annotated video.")
    return parser.parse_args()


def resolve_path(value: str) -> Path:
    path = Path(value).expanduser()
    return path.resolve() if path.is_absolute() else (PROJECT_ROOT / path).resolve()


def load_threshold(override: float | None, threshold_file: Path) -> float:
    if override is not None:
        return float(override)
    if not threshold_file.is_file():
        raise FileNotFoundError(
            f"Threshold file not found: {threshold_file}\n"
            "Run scripts/analyze_results.py first or pass --threshold <value>."
        )
    data = json.loads(threshold_file.read_text(encoding="utf-8"))
    if "image_anomaly_threshold" not in data:
        raise ValueError(f"No 'image_anomaly_threshold' key in {threshold_file}")
    return float(data["image_anomaly_threshold"])


def as_numpy(value: object) -> np.ndarray:
    if hasattr(value, "detach"):
        value = value.detach().cpu().numpy()
    return np.asarray(value)


def unpack_prediction(prediction: object) -> tuple[float, np.ndarray]:
    score = float(as_numpy(getattr(prediction, "pred_score")).reshape(-1)[0])
    anomaly_map = as_numpy(getattr(prediction, "anomaly_map")).astype(np.float32).squeeze()
    if anomaly_map.ndim != 2:
        raise RuntimeError(f"Expected a 2D anomaly map, got shape {anomaly_map.shape}")
    return score, anomaly_map


def make_boxes(anomaly_map: np.ndarray, width: int, height: int, percentile: float, min_area: int) -> list[tuple[int, int, int, int]]:
    anomaly_map = cv2.resize(anomaly_map, (width, height), interpolation=cv2.INTER_CUBIC)
    finite_values = anomaly_map[np.isfinite(anomaly_map)]
    if finite_values.size == 0 or float(finite_values.max()) <= float(finite_values.min()):
        return []

    pixel_threshold = float(np.percentile(finite_values, percentile))
    mask = (anomaly_map >= pixel_threshold).astype(np.uint8) * 255
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5, 5))
    mask = cv2.morphologyEx(mask, cv2.MORPH_CLOSE, kernel)
    mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN, kernel)

    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    boxes: list[tuple[int, int, int, int]] = []
    for contour in contours:
        if cv2.contourArea(contour) < min_area:
            continue
        x, y, box_width, box_height = cv2.boundingRect(contour)
        if box_width < 8 or box_height < 8:
            continue
        padding = 6
        x1 = max(0, x - padding)
        y1 = max(0, y - padding)
        x2 = min(width - 1, x + box_width + padding)
        y2 = min(height - 1, y + box_height + padding)
        boxes.append((x1, y1, x2, y2))
    return boxes


def main() -> None:
    args = parse_args()
    if not 0 < args.mask_percentile < 100:
        raise ValueError("--mask-percentile must be between 0 and 100.")
    if args.min_area < 0:
        raise ValueError("--min-area cannot be negative.")

    model_path = resolve_path(args.model)
    if not model_path.is_file():
        raise FileNotFoundError(
            f"Exported model not found: {model_path}\n"
            "Train a model first with scripts/train_patchcore.py."
        )
    threshold_file = resolve_path(args.threshold_file)
    image_threshold = load_threshold(args.threshold, threshold_file)

    device = "cuda" if torch.cuda.is_available() else "cpu"
    print(f"Loading model: {model_path}")
    print(f"Inference device: {device}")
    print(f"Image anomaly threshold: {image_threshold:.6f}")
    inferencer = TorchInferencer(path=str(model_path), device=device)

    camera = cv2.VideoCapture(args.camera)
    if not camera.isOpened():
        raise RuntimeError(
            f"Could not open camera index {args.camera}. On Ubuntu, verify /dev/video0 permissions "
            "and that another app is not using the camera."
        )
    if args.width > 0:
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, args.width)
    if args.height > 0:
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, args.height)

    writer = None
    save_path = resolve_path(args.save_video) if args.save_video else None
    if save_path:
        save_path.parent.mkdir(parents=True, exist_ok=True)

    frame_count = 0
    start_time = time.perf_counter()
    fps_display = 0.0
    try:
        while True:
            ok, frame = camera.read()
            if not ok:
                print("Warning: could not read a frame from the camera; retrying...")
                time.sleep(0.05)
                continue

            height, width = frame.shape[:2]
            # Anomalib expects RGB ordering for ndarray inputs; OpenCV captures BGR.
            rgb_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
            prediction = inferencer.predict(rgb_frame)
            score, anomaly_map = unpack_prediction(prediction)
            is_anomaly = score >= image_threshold
            display = frame.copy()

            if is_anomaly:
                boxes = make_boxes(anomaly_map, width, height, args.mask_percentile, args.min_area)
                for x1, y1, x2, y2 in boxes:
                    cv2.rectangle(display, (x1, y1), (x2, y2), (0, 0, 255), 2)
                label = f"ANOMALY  score={score:.4f}  threshold={image_threshold:.4f}"
                label_color = (0, 0, 255)
            else:
                label = f"NORMAL  score={score:.4f}  threshold={image_threshold:.4f}"
                label_color = (0, 180, 0)

            cv2.rectangle(display, (0, 0), (width, 38), (20, 20, 20), -1)
            cv2.putText(display, label, (10, 25), cv2.FONT_HERSHEY_SIMPLEX, 0.62, label_color, 2, cv2.LINE_AA)

            frame_count += 1
            elapsed = time.perf_counter() - start_time
            if elapsed > 0:
                fps_display = frame_count / elapsed
            cv2.putText(display, f"FPS: {fps_display:.1f} | Press Q to quit", (10, height - 12), cv2.FONT_HERSHEY_SIMPLEX, 0.55, (255, 255, 255), 1, cv2.LINE_AA)

            if save_path and writer is None:
                capture_fps = camera.get(cv2.CAP_PROP_FPS)
                if capture_fps <= 0 or capture_fps > 120:
                    capture_fps = 20.0
                writer = cv2.VideoWriter(
                    str(save_path),
                    cv2.VideoWriter_fourcc(*"mp4v"),
                    capture_fps,
                    (width, height),
                )
                if not writer.isOpened():
                    raise RuntimeError(f"Could not create output video: {save_path}")
            if writer is not None:
                writer.write(display)

            cv2.imshow("PatchCore - Live Anomaly Detection", display)
            key = cv2.waitKey(1) & 0xFF
            if key == ord("q") or key == 27:
                break
    finally:
        camera.release()
        if writer is not None:
            writer.release()
        cv2.destroyAllWindows()

    if save_path:
        print(f"Annotated video saved to: {save_path}")
    print(f"Processed {frame_count} frames.")


if __name__ == "__main__":
    main()
